import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
import 'package:lazerus_core/lazerus_core.dart';

import '../../../../../core/macros/modifiers/normalization/normalization_modifier.dart';
import '../../normalization_waveform_display.dart';
import '../macro_editor_node_module.dart';

/// Editor presentation for the audio Normalization modifier.
final class NormalizationMacroEditorNodeModule extends MacroEditorNodeModule {
  NormalizationMacroEditorNodeModule()
    : _factory = NormalizationModifierFactory();

  final NormalizationModifierFactory _factory;

  @override
  String get kind => normalizationModifierKind;

  @override
  Iterable<MacroEditorPaletteEntry> paletteEntries(
    MacroEditorNodePresentationState state,
  ) => <MacroEditorPaletteEntry>[
    const MacroEditorPaletteEntry(
      id: 'palette.normalization',
      moduleKind: normalizationModifierKind,
      section: MacroEditorPaletteSection.modules,
      icon: Icons.tune_outlined,
      title: 'Normalization',
      subtitle: 'Rolling audio dynamics',
    ),
  ];

  @override
  MacroNode? createNode(
    MacroEditorPaletteEntry entry, {
    required MacroEditorNewId newId,
  }) => _nodeWithConfiguration(
    MacroNode(
      id: newId(),
      kind: kind,
      displayName: 'Normalization',
      ports: const <MacroPortDeclaration>[],
    ),
    NormalizationModifierConfiguration(),
  );

  @override
  Widget buildInspector(
    BuildContext context,
    MacroEditorNodeViewContext nodeContext,
  ) {
    try {
      final configuration =
          NormalizationModifierConfiguration.fromNodeParameters(
            nodeContext.node.parameters,
          );
      final audioInputPortId = _factory.audioInputPortId(nodeContext.node);
      final audioSourcePortIds = nodeContext.state.graph.edges
          .where((edge) => edge.toPortId == audioInputPortId)
          .map((edge) => edge.fromPortId);
      return MacroEditorNodeInspectorCard(
        icon: Icons.tune_outlined,
        title: titleFor(nodeContext.node),
        enabled: nodeContext.state.enabled,
        onRemove: nodeContext.removeNode,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: <Widget>[
            DropdownButtonFormField<NormalizationOutputMode>(
              key: ValueKey<String>(
                'normalization-output-mode-${nodeContext.node.id}',
              ),
              initialValue: configuration.outputMode,
              decoration: const InputDecoration(
                labelText: 'Output mode',
                border: OutlineInputBorder(),
              ),
              items: const <DropdownMenuItem<NormalizationOutputMode>>[
                DropdownMenuItem<NormalizationOutputMode>(
                  value: NormalizationOutputMode.pcm,
                  child: Text('PCM audio'),
                ),
                DropdownMenuItem<NormalizationOutputMode>(
                  value: NormalizationOutputMode.value,
                  child: Text('Value (0–1)'),
                ),
              ],
              onChanged: nodeContext.state.enabled
                  ? (outputMode) {
                      if (outputMode == null ||
                          outputMode == configuration.outputMode) {
                        return;
                      }
                      nodeContext.replaceNode(
                        _nodeWithConfiguration(
                          nodeContext.node,
                          NormalizationModifierConfiguration(
                            outputMode: outputMode,
                            windowDuration: configuration.windowDuration,
                          ),
                        ),
                      );
                    }
                  : null,
            ),
            const SizedBox(height: 12),
            TextFormField(
              key: ValueKey<String>(
                'normalization-window-${nodeContext.node.id}-${configuration.windowDuration.inSeconds}',
              ),
              initialValue: configuration.windowDuration.inSeconds.toString(),
              enabled: nodeContext.state.enabled,
              keyboardType: TextInputType.number,
              inputFormatters: <TextInputFormatter>[
                FilteringTextInputFormatter.digitsOnly,
              ],
              decoration: const InputDecoration(
                labelText: 'Window N',
                suffixText: 'sec',
                border: OutlineInputBorder(),
              ),
              onChanged: (rawValue) {
                final seconds = int.tryParse(rawValue);
                if (seconds == null || seconds <= 0) return;
                final windowDuration = Duration(seconds: seconds);
                if (windowDuration > normalizationMaximumWindow) return;
                nodeContext.replaceNode(
                  _nodeWithConfiguration(
                    nodeContext.node,
                    NormalizationModifierConfiguration(
                      outputMode: configuration.outputMode,
                      windowDuration: windowDuration,
                    ),
                  ),
                );
              },
            ),
            const SizedBox(height: 8),
            Text(switch (configuration.outputMode) {
              NormalizationOutputMode.pcm =>
                'Normalizes mono PCM over the latest N seconds before audio analysis.',
              NormalizationOutputMode.value =>
                'Outputs a 0–1 value from the latest N seconds for brightness or HSV Value.',
            }),
            const SizedBox(height: 12),
            NormalizationWaveformDisplay(
              key: ValueKey<String>(
                'normalization-waveform-${nodeContext.node.id}',
              ),
              outputMode: configuration.outputMode,
              inputSourcePortIds: audioSourcePortIds,
              outputPortId: _factory.normalizedOutputPortId(nodeContext.node),
              runtimeFrames: nodeContext.state.runtimeFrames,
            ),
          ],
        ),
      );
    } on FormatException catch (error) {
      return MacroEditorNodeErrorCard(
        message: 'Normalization configuration needs repair: $error',
      );
    }
  }

  MacroNode _nodeWithConfiguration(
    MacroNode node,
    NormalizationModifierConfiguration configuration,
  ) {
    final configured = node.copyWith(
      parameters: configuration.toNodeParameters(),
    );
    return configured.copyWith(ports: _factory.portsFor(configured));
  }
}
